# RFC 8414 authorization server metadata (generated by maquina:oauth).
# Clients identify themselves with a Client ID Metadata Document, so there is
# no registration_endpoint, and offline_access is not a scope here: refresh
# tokens come with every grant.
class Oauth::AuthorizationServersController < ActionController::API
  # GET /.well-known/oauth-authorization-server
  def show
    expires_in 1.hour, public: true
    render json: {
      issuer: request.base_url,
      authorization_endpoint: new_oauth_authorization_url,
      token_endpoint: oauth_token_url,
      revocation_endpoint: oauth_revocation_url,
      response_types_supported: ["code"],
      grant_types_supported: ["authorization_code", "refresh_token"],
      code_challenge_methods_supported: ["S256"],
      token_endpoint_auth_methods_supported: ["none"],
      revocation_endpoint_auth_methods_supported: ["none"],
      scopes_supported: AccessToken::SCOPES,
      client_id_metadata_document_supported: true,
      authorization_response_iss_parameter_supported: true
    }
  end
end
